typedef float rational_t;

struct vector3d
{
  float x;
  float y;
  float z;

  vector3d(float _x, float _y, float _z) : x(_x), y(_y), z(_z) {}

  vector3d& operator*=(rational_t scale)
  {
    x *= scale;
    y *= scale;
    z *= scale;
    return *this;
  }
};

inline vector3d operator+(const vector3d& lhs, const vector3d& rhs)
{
  return vector3d(lhs.x + rhs.x, lhs.y + rhs.y, lhs.z + rhs.z);
}

class entity
{
public:
  const vector3d& get_abs_position() const;
  void set_rel_position(const vector3d& position);
};

class dolly_and_strafe_mcs
{
  char motion_control_system_layout[12];
  entity* ent;

public:
  void do_lift(rational_t distance);
};

void dolly_and_strafe_mcs::do_lift( rational_t distance )
{
  // doing lift in world coordinates
  vector3d lift(0,1,0);
  lift *= distance;
  ent->set_rel_position( ent->get_abs_position() + lift );
}
